mkitem!{mkimpl!{impl < T > Sender < T > { # [doc = " Attempts to send a message into the channel without blocking."] # [doc = ""] # [doc = " This method will either send a message into the channel immediately or return an error if"] # [doc = " the channel is full or disconnected. The returned error contains the original message."] # [doc = ""] # [doc = " If called on a zero-capacity channel, this method will send the message only if there"] # [doc = " happens to be a receive operation on the other side of the channel at the same time."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc::{channel, Receiver, Sender};"] # [doc = ""] # [doc = " let (sender, _receiver): (Sender<i32>, Receiver<i32>) = channel();"] # [doc = ""] # [doc = " assert!(sender.try_send(1).is_ok());"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn try_send (& self , msg : T) -> Result < () , TrySendError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . try_send (msg) , SenderFlavor :: List (chan) => chan . try_send (msg) , SenderFlavor :: Zero (chan) => chan . try_send (msg) , } } # [doc = " Attempts to send a value on this channel, returning it back if it could"] # [doc = " not be sent."] # [doc = ""] # [doc = " A successful send occurs when it is determined that the other end of"] # [doc = " the channel has not hung up already. An unsuccessful send would be one"] # [doc = " where the corresponding receiver has already been deallocated. Note"] # [doc = " that a return value of [`Err`] means that the data will never be"] # [doc = " received, but a return value of [`Ok`] does *not* mean that the data"] # [doc = " will be received. It is possible for the corresponding receiver to"] # [doc = " hang up immediately after this function returns [`Ok`]. However, if"] # [doc = " the channel is zero-capacity, it acts as a rendezvous channel and a"] # [doc = " return value of [`Ok`] means that the data has been received."] # [doc = ""] # [doc = " If the channel is full and not disconnected, this call will block until"] # [doc = " the send operation can proceed. If the channel becomes disconnected,"] # [doc = " this call will wake up and return an error. The returned error contains"] # [doc = " the original message."] # [doc = ""] # [doc = " If called on a zero-capacity channel, this method will wait for a receive"] # [doc = " operation to appear on the other side of the channel."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc::channel;"] # [doc = ""] # [doc = " let (tx, rx) = channel();"] # [doc = ""] # [doc = " // This send is always successful"] # [doc = " tx.send(1).unwrap();"] # [doc = ""] # [doc = " // This send will fail because the receiver is gone"] # [doc = " drop(rx);"] # [doc = " assert!(tx.send(1).is_err());"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send (& self , msg : T) -> Result < () , SendError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . send (msg , None) , SenderFlavor :: List (chan) => chan . send (msg , None) , SenderFlavor :: Zero (chan) => chan . send (msg , None) , } . map_err (| err | match err { SendTimeoutError :: Disconnected (msg) => SendError (msg) , SendTimeoutError :: Timeout (_) => unreachable ! () , }) } }}}
mkitem!{mkimpl!{impl < T > Sender < T > { # [doc = " Waits for a message to be sent into the channel, but only for a limited time."] # [doc = ""] # [doc = " If the channel is full and not disconnected, this call will block until the send operation"] # [doc = " can proceed or the operation times out. If the channel becomes disconnected, this call will"] # [doc = " wake up and return an error. The returned error contains the original message."] # [doc = ""] # [doc = " If called on a zero-capacity channel, this method will wait for a receive operation to"] # [doc = " appear on the other side of the channel."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc::channel;"] # [doc = " use std::time::Duration;"] # [doc = ""] # [doc = " let (tx, rx) = channel();"] # [doc = ""] # [doc = " tx.send_timeout(1, Duration::from_millis(400)).unwrap();"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send_timeout (& self , msg : T , timeout : Duration) -> Result < () , SendTimeoutError < T > > { match Instant :: now () . checked_add (timeout) { Some (deadline) => self . send_deadline (msg , deadline) , None => self . send (msg) . map_err (SendTimeoutError :: from) , } } # [doc = " Waits for a message to be sent into the channel, but only until a given deadline."] # [doc = ""] # [doc = " If the channel is full and not disconnected, this call will block until the send operation"] # [doc = " can proceed or the operation times out. If the channel becomes disconnected, this call will"] # [doc = " wake up and return an error. The returned error contains the original message."] # [doc = ""] # [doc = " If called on a zero-capacity channel, this method will wait for a receive operation to"] # [doc = " appear on the other side of the channel."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc::channel;"] # [doc = " use std::time::{Duration, Instant};"] # [doc = ""] # [doc = " let (tx, rx) = channel();"] # [doc = ""] # [doc = " let t = Instant::now() + Duration::from_millis(400);"] # [doc = " tx.send_deadline(1, t).unwrap();"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn send_deadline (& self , msg : T , deadline : Instant) -> Result < () , SendTimeoutError < T > > { match & self . flavor { SenderFlavor :: Array (chan) => chan . send (msg , Some (deadline)) , SenderFlavor :: List (chan) => chan . send (msg , Some (deadline)) , SenderFlavor :: Zero (chan) => chan . send (msg , Some (deadline)) , } } # [doc = " Returns `true` if the channel is empty."] # [doc = ""] # [doc = " Note: Zero-capacity channels are always empty."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (send, _recv) = mpmc::channel();"] # [doc = ""] # [doc = " let tx1 = send.clone();"] # [doc = " let tx2 = send.clone();"] # [doc = ""] # [doc = " assert!(tx1.is_empty());"] # [doc = ""] # [doc = " let handle = thread::spawn(move || {"] # [doc = "     tx2.send(1u8).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " handle.join().unwrap();"] # [doc = ""] # [doc = " assert!(!tx1.is_empty());"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_empty (& self) -> bool { match & self . flavor { SenderFlavor :: Array (chan) => chan . is_empty () , SenderFlavor :: List (chan) => chan . is_empty () , SenderFlavor :: Zero (chan) => chan . is_empty () , } } # [doc = " Returns `true` if the channel is full."] # [doc = ""] # [doc = " Note: Zero-capacity channels are always full."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (send, _recv) = mpmc::sync_channel(1);"] # [doc = ""] # [doc = " let (tx1, tx2) = (send.clone(), send.clone());"] # [doc = " assert!(!tx1.is_full());"] # [doc = ""] # [doc = " let handle = thread::spawn(move || {"] # [doc = "     tx2.send(1u8).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " handle.join().unwrap();"] # [doc = ""] # [doc = " assert!(tx1.is_full());"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn is_full (& self) -> bool { match & self . flavor { SenderFlavor :: Array (chan) => chan . is_full () , SenderFlavor :: List (chan) => chan . is_full () , SenderFlavor :: Zero (chan) => chan . is_full () , } } # [doc = " Returns the number of messages in the channel."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (send, _recv) = mpmc::channel();"] # [doc = " let (tx1, tx2) = (send.clone(), send.clone());"] # [doc = ""] # [doc = " assert_eq!(tx1.len(), 0);"] # [doc = ""] # [doc = " let handle = thread::spawn(move || {"] # [doc = "     tx2.send(1u8).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " handle.join().unwrap();"] # [doc = ""] # [doc = " assert_eq!(tx1.len(), 1);"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn len (& self) -> usize { match & self . flavor { SenderFlavor :: Array (chan) => chan . len () , SenderFlavor :: List (chan) => chan . len () , SenderFlavor :: Zero (chan) => chan . len () , } } # [doc = " If the channel is bounded, returns its capacity."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (send, _recv) = mpmc::sync_channel(3);"] # [doc = " let (tx1, tx2) = (send.clone(), send.clone());"] # [doc = ""] # [doc = " assert_eq!(tx1.capacity(), Some(3));"] # [doc = ""] # [doc = " let handle = thread::spawn(move || {"] # [doc = "     tx2.send(1u8).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " handle.join().unwrap();"] # [doc = ""] # [doc = " assert_eq!(tx1.capacity(), Some(3));"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn capacity (& self) -> Option < usize > { match & self . flavor { SenderFlavor :: Array (chan) => chan . capacity () , SenderFlavor :: List (chan) => chan . capacity () , SenderFlavor :: Zero (chan) => chan . capacity () , } } # [doc = " Returns `true` if senders belong to the same channel."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(mpmc_channel)]"] # [doc = ""] # [doc = " use std::sync::mpmc;"] # [doc = ""] # [doc = " let (tx1, _) = mpmc::channel::<i32>();"] # [doc = " let (tx2, _) = mpmc::channel::<i32>();"] # [doc = ""] # [doc = " assert!(tx1.same_channel(&tx1));"] # [doc = " assert!(!tx1.same_channel(&tx2));"] # [doc = " ```"] # [unstable (feature = "mpmc_channel" , issue = "126840")] pub fn same_channel (& self , other : & Sender < T >) -> bool { match (& self . flavor , & other . flavor) { (SenderFlavor :: Array (a) , SenderFlavor :: Array (b)) => a == b , (SenderFlavor :: List (a) , SenderFlavor :: List (b)) => a == b , (SenderFlavor :: Zero (a) , SenderFlavor :: Zero (b)) => a == b , _ => false , } } }}}
